import { useMemo, useState } from 'react';
import {
  Badge,
  Button,
  Card,
  Chip,
  EmptyState,
  Pagination,
  Stack,
  Text,
} from '@jinx-ui/react';

type Status = 'active' | 'paused' | 'over' | 'archived';

type Project = {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: Status;
};

const STATUS_LABEL: Record<Status, string> = {
  active: 'Активен',
  paused: 'На паузе',
  over: 'Превышение',
  archived: 'В архиве',
};

const STATUS_TONE: Record<Status, 'success' | 'warning' | 'danger' | 'neutral'> = {
  active: 'success',
  paused: 'warning',
  over: 'danger',
  archived: 'neutral',
};

const ALL_STATUSES: Status[] = ['active', 'paused', 'over', 'archived'];

const PROJECTS: Project[] = [
  { id: 'p-1', name: 'Атлас. Витрина данных', used: 412, quota: 500, status: 'active' },
  { id: 'p-2', name: 'Биллинг: миграция на v3', used: 780, quota: 600, status: 'over' },
  { id: 'p-3', name: 'Мобильный клиент', used: 145, quota: 400, status: 'active' },
  { id: 'p-4', name: 'Поисковый индекс', used: 260, quota: 300, status: 'paused' },
  { id: 'p-5', name: 'Отчётность для финотдела', used: 90, quota: 250, status: 'archived' },
  { id: 'p-6', name: 'Антифрод-скоринг', used: 340, quota: 350, status: 'active' },
  { id: 'p-7', name: 'Складская интеграция', used: 55, quota: 200, status: 'paused' },
  { id: 'p-8', name: 'Рекомендации на главной', used: 520, quota: 450, status: 'over' },
  { id: 'p-9', name: 'Внутренний портал', used: 30, quota: 150, status: 'archived' },
  { id: 'p-10', name: 'Пайплайн видеотранскода', used: 180, quota: 500, status: 'active' },
  { id: 'p-11', name: 'Сервис уведомлений', used: 210, quota: 220, status: 'active' },
  { id: 'p-12', name: 'Архив логов', used: 70, quota: 400, status: 'archived' },
];

const PAGE_SIZE = 5;
const RING_RADIUS = 18;
const RING_LENGTH = 2 * Math.PI * RING_RADIUS;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<Status[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const visible = useMemo(
    () => PROJECTS.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(visible.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount);
  const rows = visible.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);

  const removeStatus = (status: Status) => {
    setActiveStatuses((current) => current.filter((item) => item !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(ALL_STATUSES);
    setPage(1);
  };

  return (
    <Card className="jx-p-4">
      <Stack direction="vertical" gap="lg">
        <Stack direction="vertical" gap="xs">
          <Text as="h2" variant="heading-sm">
            Расход по проектам
          </Text>
          <Text variant="body-sm" tone="muted">
            Показано {visible.length} из {PROJECTS.length}
          </Text>
        </Stack>

        <Stack direction="horizontal" gap="sm" wrap>
          {activeStatuses.map((status) => (
            <Chip
              key={status}
              tone={STATUS_TONE[status]}
              onRemove={() => removeStatus(status)}
              removeLabel={`Убрать фильтр «${STATUS_LABEL[status]}»`}
            >
              {STATUS_LABEL[status]}
            </Chip>
          ))}
        </Stack>

        {rows.length === 0 ? (
          <EmptyState
            title="Нет проектов под выбранные фильтры"
            description="Снятые статусы скрыли все строки. Верните фильтры, чтобы увидеть список."
            action={
              <Button variant="primary" onClick={resetFilters}>
                Сбросить фильтры
              </Button>
            }
          />
        ) : (
          <Stack direction="vertical" gap="sm">
            {rows.map((project) => {
              const percent = Math.round((project.used / project.quota) * 100);
              const arc = Math.min(percent, 100);
              const ringColor =
                project.status === 'over'
                  ? 'var(--jx-color-danger)'
                  : project.status === 'paused'
                    ? 'var(--jx-color-warning)'
                    : 'var(--jx-color-accent)';

              return (
                <Card key={project.id} variant="outlined" className="jx-p-3">
                  <Stack direction="horizontal" gap="md" align="center" justify="between">
                    <Stack direction="horizontal" gap="md" align="center">
                      <svg
                        width={44}
                        height={44}
                        viewBox="0 0 44 44"
                        role="img"
                        aria-label={`Квота заполнена на ${percent} процентов`}
                      >
                        <circle
                          cx={22}
                          cy={22}
                          r={RING_RADIUS}
                          fill="none"
                          stroke="var(--jx-color-border-subtle)"
                          strokeWidth={4}
                        />
                        <circle
                          cx={22}
                          cy={22}
                          r={RING_RADIUS}
                          fill="none"
                          stroke={ringColor}
                          strokeWidth={4}
                          strokeLinecap="round"
                          strokeDasharray={RING_LENGTH}
                          strokeDashoffset={RING_LENGTH * (1 - arc / 100)}
                          transform="rotate(-90 22 22)"
                        />
                      </svg>

                      <Stack direction="vertical" gap="xs">
                        <Text variant="body-md">{project.name}</Text>
                        <Text variant="body-sm" tone="muted">
                          {percent}% · {project.used} из {project.quota} ч
                        </Text>
                      </Stack>
                    </Stack>

                    <Badge tone={STATUS_TONE[project.status]}>
                      {STATUS_LABEL[project.status]}
                    </Badge>
                  </Stack>
                </Card>
              );
            })}

            <Pagination page={safePage} pageCount={pageCount} onPageChange={setPage} />
          </Stack>
        )}
      </Stack>
    </Card>
  );
}

